=20, tx="建造一口法力之井，使你和附近坐下的其他人每5秒恢复29点法力值，与智慧祝福不叠加。", fn=""}, {zh="发酵桶", en="Fermenter", sk=140, tx="放置一个发酵桶，允许制造特定材料，并提供法力之井的所有增益。", fn="原位替换法力之井，继承增益；并可现场发酵酿造特定炼金材料。"}, {zh="炼金实验室", en="Alchemy Laboratory", sk=300, tx="放置一个炼金实验室，可用于需要它的配方，并提供法力之井的所有增益。", fn="原位替换法力之井/发酵桶，继承增益；充当野外炼金实验室（可替代通灵学院/黑石塔做合剂）。"}}, blacksmithing={{zh="磨刀石", en="Sharpening Wheel", sk=20, tx="搭建一个磨刀石，使你和附近坐下的其他人力量提高34，与大地之力图腾互斥。", fn=""}, {zh="铁砧", en="Anvil", sk=140, tx="放置一个铁砧，并提供磨刀石的所有增益。", fn="原位替换磨刀石，继承增益；并放下一座便携铁砧（锻造/工程现场制造用）。"}, {zh="大师级熔炉", en="Master Forge", sk=300, tx="放置一个大师级熔炉，可用于需要它的配方，并提供磨刀石的所有增益。", fn="原位替换磨刀石/铁砧，继承增益；并放下大师级熔炉（可替代黑石深渊熔炉）。"}}, enchanting={{zh="附魔的鲁特琴", en="Enchanted Lute", sk=20, tx="召唤一把附魔的鲁特琴，使你和附近坐下的其他人获得308 点护甲值，另有 全属性 +13、全抗性 +22，与野性印记不叠加。", fn="一件顶三样：护甲、全属性、全抗性写在同一个增益里。"}, {zh="奥术回收器", en="Arcane Salvager", sk=140, tx="放置一个奥术回收器，能够更高效地进行分解，并提供附魔的鲁特琴的所有增益。", fn="原位替换鲁特琴，继承增益；并让野外分解更高效。"}, {zh="奥术熔炉", en="Arcane Forge", sk=300, tx="放置一座奥术熔炉，可用于需要它的配方，并提供附魔的鲁特琴的所有增益。", fn="原位替换鲁特琴/回收器，继承增益；并放下奥术熔炉（顶级附魔配方要用）。"}}, engineering={{zh="试剂机器人", en="Reagent Bot", sk=20, tx="召唤一个试剂机器人，允许你和附近的其他人购买材料。", fn="召唤试剂机器人，你和附近的人可以就地购买施法材料。不给属性增益。"}, {zh="修理机器人", en="Repair Bot", sk=140, tx="召唤一个修理机器人，允许你和附近的其他人购买材料和修理装备。", fn="原位替换试剂机器人：继承买材料；并现场修理装备。"}, {zh="无政府主义者的工作台", en="Anarchist's Workbench", sk=300, tx="放置一个无政府主义者的工作台，可用于需要它的配方。", fn="放下专属工作台（需要该环境的高阶工程配方用）。"}}, leatherworking={{zh="营地帐篷", en="Camp Tent", sk=20, tx="搭建一座帐篷，使你和附近坐下的其他人获得充分休息经验值，最多可累积至当前等级所需经验值的5%。若已有的充分休息经验超过该数值，则不生效。", fn="野外便携旅店：帐篷旁就座即把休息经验补到满一级的 5%（已经超过则无效）。不占任何团队增益位。"}, {zh="制革架", en="Tanning Rack", sk=140, tx="放置一个制革架，允许制造特定材料，并提供营地帐篷的所有增益。", fn="原位替换帐篷，继承帐篷全部效果；并可在野外制作特定制皮材料。"}, {zh="缝纫机", en="Sewing Machine", sk=300, tx="放置一台缝纫机，可用于需要它的配方，并提供营地帐篷的所有增益。", fn="原位替换帐篷/制革架，继承全部效果；并充当野外缝纫机环境（高阶配方要用）。"}}, tailoring={{zh="阵营旗帜", en="Faction Banner", sk=20, tx="展开一面旗帜，使你和附近坐着的本阵营的其他成员的精神提高32。与神圣之灵互斥。", fn="部落/联盟各一款，只对本阵营就座的人生效。"}, {zh="纺车", en="Spinning Wheel", sk=140, tx="放置一个纺车，允许制造特定材料，并提供阵营旗帜的所有增益。", fn="原位替换旗帜，继承增益；并可在野外制作特定裁缝材料。"}, {zh="织布机", en="Loom", sk=300, tx="放置一台织布机，可用于需要它的配方，并提供阵营旗帜的所有增益。", fn="原位替换旗帜/纺车，继承增益；并放下高阶织布机（顶级配方要用）。"}}, herbalism={{zh="熏香蜡烛", en="Incense Candle", sk=20, tx="点燃一根熏香蜡烛，使你和附近坐下的其他人智力提高25点，与奥术智慧不叠加。", fn=""}, {zh="温室", en="Greenhouse", sk=140, tx="放置一个温室，随着时间的推移，播种的种子会生长成草药，并提供熏香蜡烛的所有增益。", fn="原位替换蜡烛，继承增益；播下的种子会随时间长成草药，全队都能采。"}, {zh="种子杂交器", en="Seed Hybridizer", sk=300, tx="放置一个种子杂交器，允许将种子繁殖或组合成更稀有的级别，并提供熏香蜡烛的所有增益。", fn="原位替换蜡烛/温室，继承增益；可把种子增殖或杂交成更稀有的种子。"}}, mining={{zh="磁石", en="Lodestone", sk=20, tx="竖起一块磁石，使你和附近坐下的其他人近战攻击强度提高90，与力量祝福互斥。", fn=""}, {zh="岩石园", en="Rock Garden", sk=140, tx="放置一个岩石园，随着时间的推移会生成普通的采矿点，并提供磁石的所有增益。", fn="原位替换磁石，继承增益；并随时间就地长出普通矿点，全队都能采。"}, {zh="熔火铸造厂", en="Molten Foundry", sk=300, tx="放置一个熔火铸造厂，可用于需要它的配方，并提供磁石的所有增益。", fn="原位替换磁石/岩石园，继承增益；并放下熔火铸造厂（野外高阶熔炼）。"}}, skinning={{zh="营地椅子", en="Camp Chair", sk=20, tx="组装一把营地椅子，使你和附近坐下的其他人所有法术和攻击的爆击几率提高2%，与枭兽光环不叠加。", fn="爆击对物理和法术同时生效。"}, {zh="野外指南", en="Field Guide", sk=140, tx="放置一本野外指南，允许玩家阅读并获得追踪野兽技能，并提供营地椅子的所有增益。", fn="原位替换椅子，继承增益；任何人读一下就能获得【追踪野兽】。"}, {zh="捕兽者工作台", en="Trapper's Workbench", sk=300, tx="放置一个捕兽者工作台，内含1个陷阱，并提供营地椅子的所有增益。", fn="原位替换椅子/野外指南，继承增益；台子上带 1 个陷阱给团队用。"}}, cooking={{zh="曲奇的大餐", en="Cookie's Feast", sk=145, tx="摆出曲奇的大餐，其中包含可提高耐力的食物。", fn="摆一桌耐力食物（需要营火）。"}, {zh="铁炉", en="Iron Oven", sk=300, tx="放置一个铁炉，可供最高级的烹饪配方使用。", fn="放下铁炉，最高阶的烹饪配方要用它。"}}, firstaid={{zh="急救包", en="First Aid Kit", sk=20, tx="打开一个急救包，使你和附近坐下的其他人耐力提高56点，与真言术：韧不叠加。", fn=""}, {zh="毒素研究", en="Toxin Study", sk=140, tx="放置一个毒素研究，内含治疗药水和抗毒药剂，并提供急救包的所有增益。", fn="原位替换急救包，继承增益；里面备有治疗药水和抗毒药。"}, {zh="瘟疫医生实验室", en="Plague Doctor's Laboratory", sk=300, tx="放置一个瘟疫医生实验室，内含治疗药水和药膏，并提供急救包的所有增益。", fn="原位替换急救包，继承增益；里面备有治疗药水和药膏。"}}, fishing={{zh="鱼缸", en="Fish Bowl", sk=20, tx="放置一个小的鱼缸，使你和附近坐下的其他人所有属性提高8%，与王者祝福不叠加。", fn="全属性百分比增益，法系物理都吃。"}, {zh="钓鱼架", en="Fishing Rack", sk=140, tx="放置一个钓鱼架，使你能够钓到优秀的鱼，持续1 小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。", fn="原位替换鱼缸，继承增益；一段时间内能钓上优秀品质的鱼，并提供钓鱼技能鱼饵。"}, {zh="钓鱼小屋", en="Fishing Hut", sk=300, tx="放置一个钓鱼小屋，使你能够钓到稀有的鱼，持续1 小时，提供钓鱼技能鱼饵，并提供鱼缸的所有增益。", fn="原位替换鱼缸/钓鱼架，继承增益；一段时间内能钓上稀有品质的鱼，并提供钓鱼技能鱼饵。"}}}}, blueprints={{dun="洛丹伦废墟", slug="ruins-of-lordaeron", boss="拉斯玛尔", id=273085, zh="蓝图：发酵桶", en="Blueprint: Fermenter", prof="炼金术"}, {dun="洛丹伦废墟", slug="ruins-of-lordaeron", boss="拉斯玛尔", id=273103, zh="蓝图：奥术回收器", en="Blueprint: Arcane Salvager", prof="附魔"}, {dun="挖掘场", slug="excavation-site", boss="影牙", id=273106, zh="蓝图：温室", en="Blueprint: Greenhouse", prof="书"}, {dun="挖掘场", slug="excavation-site", boss="遗物守护者", id=273097, zh="蓝图：岩石花园", en="Blueprint: Rock Garden", prof="书"}, {dun="达拉然城", slug="city-of-dalaran", boss="不稳定的哨兵", id=273099, zh="蓝图：纺车", en="Blueprint: Spinning Wheel", prof="裁缝"}, {dun="达拉然城", slug="city-of-dalaran", boss="大法师之影", id=273103, zh="蓝图：奥术回收器", en="Blueprint: Arcane Salvager", prof="附魔"}, {dun="死亡矿井", slug="the-deadmines", boss="斯尼德", id=273092, zh="蓝图：修理机器人", en="Blueprint: Repair Bot", prof="工程学"}, {dun="死亡矿井", slug="the-deadmines", boss="基尔尼格", id=273086, zh="蓝图：铁砧", en="Blueprint: Anvil", prof="锻造"}, {dun="死亡矿井", slug="the-deadmines", boss="曲奇", id=273102, zh="蓝图：曲奇的盛宴", en="Blueprint: Cookie's Feast", prof="烹饪"}, {dun="哀嚎洞穴", slug="wailing-caverns", boss="安娜科德拉", id=273098, zh="蓝图：野外指南", en="Blueprint: Field Guide", prof="书"}, {dun="哀嚎洞穴", slug="wailing-caverns", boss="瑟芬迪斯", id=273087, zh="蓝图：中级营火", en="Blueprint: Journeyman Campfire", prof="烹饪"}, {dun="影牙城堡", slug="shadowfang-keep", boss="屠夫拉佐克劳", id=273096, zh="蓝图：制革架", en="Blueprint: Tanning Rack", prof="制皮"}, {dun="影牙城堡", slug="shadowfang-keep", boss="指挥官斯普林瓦尔", id=273105, zh="蓝图：毒素研究", en="Blueprint: Toxin Study", prof="急救"}, {dun="剃刀沼泽", slug="razorfen-kraul", boss="卡尔加·刺肋", id=273103, zh="蓝图：奥术回收器", en="Blueprint: Arcane Salvager", prof="附魔"}, {dun="黑暗深渊", slug="blackfathom-deeps", boss="格里哈斯特", id=273141, zh="蓝图：钓鱼架", en="Blueprint: Fishing Rack", prof="钓鱼"}}, legacy={{zh="厨师长", en="Master Chef", max=5, d="你的烹饪配方有50%的几率额外生成一份成品。", dEn="Your cooking recipes h